    const free = freeSlots(busy, dayStart, dayEnd, 0);
    const next: Iv[] = [];
    for (const [as, ae] of common) {
      for (const [bs, be] of free) {
        const s = Math.max(as, bs);
        const e = Math.min(ae, be);
        if (e >= s) next.push([s, e]);
      }
    }
    common = next;
  }
  for (const [s, e] of common) {
    if (e - s >= len) return s;
  }
  return null;
}

